<?php
require_once __DIR__ . '/db_connection.php';
$pdo = getDB();
$mensajeExito = '';
$errorAgenda  = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['agendar_publico'])) {
    $nutriologoId = (int)($_POST['nutriologo_id'] ?? 1);
        $nombre   = trim($_POST['nombre'] ?? '');
            $telefono = trim($_POST['telefono'] ?? '');
                $email    = trim($_POST['email'] ?? '');
                    $fecha    = $_POST['fecha_cita'] ?? '';
                        $hora     = $_POST['hora_inicio'] ?? '';
                            $tipo     = $_POST['tipo_cita'] ?? 'primera_vez';
                                $motivo   = trim($_POST['motivo'] ?? '');

                                    if ($nombre && $telefono && $fecha && $hora) {
                                            $stmtCheck = $pdo->prepare("SELECT COUNT(*) FROM citas WHERE nutriologo_id = ? AND fecha_cita = ? AND hora_inicio = ? AND estado NOT IN ('cancelada', 'no_asistio')");
                                                    $stmtCheck->execute([$nutriologoId, $fecha, $hora]);
                                                            if ($stmtCheck->fetchColumn() > 0) {
                                                                        $errorAgenda = "Horario ocupado con el especialista seleccionado. Por favor elige otra hora.";
                                                                                } else {
                                                                                            $horaFin = date('H:i:s', strtotime($hora . ' + 45 minutes'));
                                                                                                        $stmt = $pdo->prepare("INSERT INTO citas (nutriologo_id, nombre_prospecto, telefono_prospecto, email_prospecto, fecha_cita, hora_inicio, hora_fin, tipo_cita, origen, estado, motivo_notas) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'landing_web', 'pendiente_confirmar', ?)");
                                                                                                                    $stmt->execute([$nutriologoId, $nombre, $telefono, $email, $fecha, $hora, $horaFin, $tipo, $motivo]);
                                                                                                                                $mensajeExito = "¡Solicitud enviada a Recepción! Te confirmaremos por WhatsApp.";
                                                                                                                                        }
                                                                                                                                            }
                                                                                                                                            }
                                                                                                                                            $especialistas = $pdo->query("SELECT * FROM usuarios WHERE rol = 'nutriologo' AND activo = 1 ORDER BY id ASC")->fetchAll();
                                                                                                                                            ?>
